output_text:
[
  {
    "id": "no_carts_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles, i.e. narrow passages with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "A shopper must not move northward into a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileNorthwardWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileNorthwardWithCart"
    }
  },
  {
    "id": "park_cart_at_single_file_mouth",
    "text": "When interacting with a cart at the mouth of a single-file shelf aisle, the shopper is obliged to park the cart there before proceeding.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "gt": [
            "freeWidthH",
            6
          ]
        },
        "singleFileAisleMouth": {
          "and": [
            "wideCrossAisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "cartParkingAttemptAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkingAttemptAtMouth",
      "discharge": {
        "not": "hasCart"
      }
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle_item",
    "text": "After servicing or collecting an item in a single-file shelf aisle without a cart, the shopper is obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartlessServiceInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessServiceInSingleFileAisle",
      "discharge": "hasCart"
    }
  },
  {
    "id": "drop_cart_only_at_aisle_mouth",
    "text": "A shopper may leave or park a cart only at the designated wide aisle mouths leading into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "gt": [
            "freeWidthH",
            6
          ]
        },
        "singleFileAisleMouth": {
          "and": [
            "wideCrossAisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "singleFileAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "pickup_cart_only_at_rack_or_parked_mouth",
    "text": "A shopper may acquire a cart only from the cart rack or from a previously used aisle-mouth parking point.",
    "abstraction": {
      "state_properties": {
        "cartRack": "at(1,7)",
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedCartPickupPlace": {
          "or": [
            "cartRack",
            "singleFileAisleMouth"
          ]
        }
      },
      "events": {
        "pickupCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pickupCart",
          {
            "not": "allowedCartPickupPlace"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_service_in_single_file",
    "text": "Shelf interactions performed from a single-file aisle must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "serviceInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "serviceInSingleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "one_way_no_west_movement",
    "text": "The supermarket traffic convention forbids westward movement, making shoppers follow an eastward one-way flow through the store.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
